-- Batch 4/12: Cardiac Emergencies MCQs 76-100
-- Focus: Hypertensive Emergencies, Aortic Dissection, Pericardial Disease
-- Sources: Tintinalli 9e Ch 53-57, Case Files EM 5e, Roberts & Hedges 7e

DO $$
DECLARE
    tid UUID;
BEGIN
    SELECT id INTO tid FROM topics WHERE slug = 'em-cardiac-emergencies' LIMIT 1;
    IF tid IS NULL THEN RAISE EXCEPTION 'Topic not found'; END IF;


END $$;
