    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (tid, '76. A 52-year-old with BP 220/130 presents with headache, blurred vision, and papilledema. Creatinine is rising. What is the diagnosis?', '["Hypertensive urgency", "Hypertensive emergency", "Essential hypertension", "White coat hypertension"]', 1, 'Hypertensive emergency = BP >180/120 WITH end-organ damage (encephalopathy, papilledema, AKI, aortic dissection, acute MI, pulmonary edema). Urgency = elevated BP without end-organ damage.'),
    (tid, '77. In hypertensive emergency, what is the BP reduction goal in the first hour?', '["Normalize to 120/80", "Reduce MAP by no more than 25%", "Reduce SBP to below 140", "Reduce DBP to below 90"]', 1, 'Rapid normalization risks watershed ischemia. Reduce MAP by ≤25% in the first hour, then to 160/100-110 over 2-6 hours, then gradually to normal over 24-48 hours.'),
    (tid, '78. Which IV antihypertensive is preferred for hypertensive emergency with acute pulmonary edema?', '["IV nicardipine", "IV nitroglycerin or nitroprusside", "IV labetalol", "IV hydralazine"]', 1, 'Nitroglycerin reduces preload (venodilation) and afterload, rapidly improving pulmonary congestion. Nitroprusside is an alternative that provides balanced arterial and venous dilation.'),
    (tid, '79. A patient with acute aortic dissection has BP 210/120. Which medication combination is first-line?', '["IV nicardipine alone", "IV esmolol (rate control first) then nitroprusside if needed", "IV hydralazine", "Oral nifedipine"]', 1, 'In aortic dissection, heart rate control MUST precede afterload reduction. Beta-blockers (esmolol, labetalol) reduce HR and dP/dt (aortic wall shear stress). Vasodilators alone cause reflex tachycardia, worsening dissection.'),
    (tid, '80. Stanford Type A aortic dissection involves which portion of the aorta?', '["Descending aorta only", "Ascending aorta (regardless of distal extension)", "Abdominal aorta", "Aortic arch only"]', 1, 'Stanford Type A involves the ascending aorta (with or without distal extension) and requires emergent surgical repair. Type B involves only the descending aorta and is typically managed medically.'),
    (tid, '81. Which imaging modality is the gold standard for diagnosing aortic dissection in unstable patients?', '["Chest X-ray", "CT angiography of the aorta", "Transesophageal echocardiography (TEE)", "MRI"]', 2, 'TEE can be performed at the bedside in unstable patients with excellent sensitivity (98%) and specificity (95%). CTA is preferred in stable patients due to rapid acquisition and availability.'),
    (tid, '82. A 35-year-old tall male with pectus excavatum and lens subluxation presents with sudden tearing chest pain. What underlying condition predisposes to aortic dissection?', '["Ehlers-Danlos syndrome", "Marfan syndrome", "Turner syndrome", "Down syndrome"]', 1, 'Marfan syndrome (FBN1 mutation) causes cystic medial necrosis of the aorta, predisposing to dissection at a young age. Classic features: tall stature, arachnodactyly, lens subluxation, pectus deformity.'),
    (tid, '83. A patient presents with pleuritic chest pain relieved by sitting forward. ECG shows diffuse concave ST elevation and PR depression. What is the treatment?', '["Emergent PCI", "NSAIDs (ibuprofen) and colchicine", "Antibiotics", "Pericardiocentesis"]', 1, 'Acute pericarditis is treated with NSAIDs (ibuprofen 600mg TID) plus colchicine (0.5mg BID) for symptom relief and to prevent recurrence. Avoid aspirin in post-MI pericarditis (Dressler) to prevent coronary vasospasm.'),
    (tid, '84. A post-MI patient develops fever, pleuritic chest pain, and pericardial friction rub 3 weeks after the event. What is this condition called?', '["Early post-MI pericarditis", "Dressler syndrome (post-myocardial infarction syndrome)", "Recurrent MI", "Pulmonary embolism"]', 1, 'Dressler syndrome is an autoimmune pericarditis occurring 2-10 weeks post-MI. It presents with fever, pleuritic chest pain, pericardial effusion, and elevated ESR/CRP. Treated with aspirin and colchicine.'),
    (tid, '85. What is the most sensitive physical exam finding for cardiac tamponade?', '["Muffled heart sounds", "Pulsus paradoxus >10 mmHg", "Distended neck veins", "Tachycardia"]', 1, 'Pulsus paradoxus (>10 mmHg drop in SBP during inspiration) is the most sensitive finding for tamponade. It occurs because the distended pericardium prevents normal RV expansion, causing exaggerated ventricular interdependence.'),
    (tid, '86. On echocardiography, what finding indicates hemodynamically significant pericardial effusion?', '["Trivial anterior effusion", "RV diastolic collapse", "Mild LV hypertrophy", "Aortic root dilation"]', 1, 'RV diastolic collapse (and RA systolic collapse) on echo indicates that pericardial pressure exceeds intracardiac pressure, confirming hemodynamic compromise (tamponade physiology).'),
    (tid, '87. A cocaine user presents with severe chest pain, diaphoresis, and BP 200/120. ECG shows ST elevation in V1-V4. Which medication is CONTRAINDICATED?', '["Nitroglycerin", "Benzodiazepines", "Beta-blockers (metoprolol)", "Aspirin"]', 2, 'Beta-blockers are contraindicated in cocaine-induced ACS because they allow unopposed alpha-adrenergic stimulation, worsening coronary vasospasm and hypertension. Use benzodiazepines, nitrates, and phentolamine instead.'),
    (tid, '88. In cocaine-induced chest pain with STEMI, what is the preferred management for coronary vasospasm?', '["IV metoprolol", "Benzodiazepines + nitroglycerin + PCI if refractory", "IV esmolol", "Observation"]', 1, 'Cocaine causes coronary vasospasm and thrombosis. Benzodiazepines reduce sympathetic drive, nitroglycerin reverses vasospasm, and PCI is performed if STEMI criteria persist despite medical therapy.'),
    (tid, '89. What is the most dangerous complication of a hypertensive emergency affecting the brain?', '["Migraine", "Hypertensive encephalopathy progressing to hemorrhagic stroke", "Tension headache", "Transient ischemic attack"]', 1, 'Hypertensive encephalopathy occurs when BP exceeds cerebral autoregulation limits, causing cerebral edema. Without treatment, it can progress to hemorrhagic stroke, seizures, and death.'),
    (tid, '90. A pregnant woman at 34 weeks presents with BP 170/110, headache, visual changes, and proteinuria. Platelets are 85K. What is the diagnosis?', '["Gestational hypertension", "Severe preeclampsia with HELLP syndrome", "Chronic hypertension", "Eclampsia"]', 1, 'Severe preeclampsia (BP >160/110 + symptoms) with HELLP (Hemolysis, Elevated Liver enzymes, Low Platelets) requires IV magnesium sulfate for seizure prophylaxis and expedited delivery.'),
    (tid, '91. What is the drug of choice for seizure prophylaxis in eclampsia?', '["IV diazepam", "IV magnesium sulfate", "IV phenytoin", "IV levetiracetam"]', 1, 'Magnesium sulfate is superior to all other anticonvulsants for eclamptic seizure prevention and treatment (MAGPIE trial). Loading dose: 4-6g IV over 15-20 min, then 1-2g/hr maintenance.'),
    (tid, '92. Which antihypertensive is preferred for acute BP control in preeclampsia?', '["IV nitroprusside", "IV labetalol or IV hydralazine", "Oral ACE inhibitor", "Oral nifedipine XL"]', 1, 'IV labetalol (20mg, then escalating doses) or IV hydralazine (5-10mg) are first-line for acute BP control in preeclampsia. ACE inhibitors are teratogenic and absolutely contraindicated in pregnancy.'),
    (tid, '93. A patient with pheochromocytoma has BP 240/140 with severe headache and palpitations. What is the first-line treatment?', '["IV labetalol", "IV phentolamine (alpha-blocker)", "IV esmolol", "Oral clonidine"]', 1, 'Pheochromocytoma hypertensive crisis requires alpha-blockade FIRST with phentolamine. Beta-blockers alone cause unopposed alpha stimulation and paradoxical hypertension. Alpha-blockade must precede beta-blockade.'),
    (tid, '94. What is constrictive pericarditis and how does it differ from tamponade?', '["Both have pulsus paradoxus", "Constriction shows calcified pericardium with Kussmaul sign; tamponade shows pulsus paradoxus without Kussmaul sign", "They are clinically identical", "Constriction is always acute"]', 1, 'Constrictive pericarditis has a thickened/calcified pericardium restricting filling (Kussmaul sign = JVP rises with inspiration). Tamponade has fluid compression with pulsus paradoxus. Kussmaul sign is absent in tamponade.'),
    (tid, '95. A patient with end-stage renal disease on dialysis presents with dyspnea and a large pericardial effusion. What is the most likely etiology?', '["Viral pericarditis", "Uremic pericarditis", "Bacterial pericarditis", "Malignant pericarditis"]', 1, 'Uremic pericarditis occurs in advanced renal failure (BUN typically >60 mg/dL). It is an indication for urgent dialysis. The pericardial fluid is often hemorrhagic.'),
    (tid, '96. Which of the following is a Type B aortic dissection complication that requires emergent surgery?', '["Controlled hypertension on medication", "Malperfusion syndrome (visceral or limb ischemia)", "Stable back pain", "Pleural effusion"]', 1, 'Type B dissections are managed medically unless complicated by malperfusion (renal, mesenteric, or limb ischemia), rupture, rapid expansion, or refractory pain/hypertension, which require intervention.'),
    (tid, '97. What is the D-dimer role in aortic dissection?', '["No utility", "A negative D-dimer can help rule out acute aortic dissection in low-risk patients", "Confirms dissection if positive", "Used to monitor treatment response"]', 1, 'A negative D-dimer (<500 ng/mL) has a >95% negative predictive value for acute aortic dissection in low-pretest-probability patients (ADD-RS score 0-1). It cannot confirm dissection if positive.'),
    (tid, '98. A patient with known abdominal aortic aneurysm presents with sudden severe abdominal pain, hypotension, and a pulsatile abdominal mass. What is the management?', '["CT scan first", "Emergent surgical repair without delay", "IV antibiotics", "Observation with serial exams"]', 1, 'Ruptured AAA (triad: abdominal/back pain, hypotension, pulsatile mass) has >80% mortality if untreated. Emergent open repair or EVAR is required. Do NOT delay for imaging in a hemodynamically unstable patient.'),
    (tid, '99. In a patient with suspected aortic dissection, which pulse finding is most suggestive?', '["Bounding pulses bilaterally", "Pulse deficit (absent or diminished pulse in one extremity)", "Pulsus alternans", "Pulsus bisferiens"]', 1, 'Pulse deficit occurs when the dissection flap occludes a branch artery. BP differential >20 mmHg between arms is present in ~20% of Type A dissections and is a classic but not universal finding.'),
    (tid, '100. What is the most common cause of secondary hypertension in young adults?', '["Pheochromocytoma", "Renal artery stenosis (fibromuscular dysplasia)", "Primary aldosteronism", "Coarctation of the aorta"]', 1, 'Fibromuscular dysplasia (FMD) causing renal artery stenosis is the most common cause of secondary HTN in young women. It shows a "string of beads" appearance on angiography and responds to angioplasty.');
